300	// True if adding `date` keeps every 7-day window at or under the cap.
301	function fitsCap(kept, date) {
302	  for (let start = addDays(date, -6); start <= date; start = addDays(start, 1)) {
303	    const end = addDays(start, 6);
304	    const inWindow = kept.filter((r) => r.date >= start && r.date <= end).length;
