310	// Decided: a material consequence must always be announced, so this is never paused.
311	const NEVER_PAUSED = ["before_default"];
312	
313	/**
314	 * Every reminder for this advance as known today, each with a status:
315	 * "sent" (on or before today), "scheduled" (later, if nothing changes) or "paused".
316	 * Notices about events win over routine late reminders when the 2-a-week cap bites.
317	 * Nothing is sent on or after the default date.
318	 */
319	export function getReminders(advance, today) {
320	  const repaid_on = repaidOn(advance, today);
321	  const owedOn = (date) => repaid_on == null || repaid_on >= date;
322	  const due = advance.due_date;
323	  const failed = failedAttemptOn(advance, due, today);
324	  const lateKnown = failed != null || (today > due && owedOn(due));
325	  const candidates = [];
326	
327	  const beforeDue = addDays(due, -REMINDER_DAYS_BEFORE_DUE);
328	  if (beforeDue >= advance.accepted_on && owedOn(beforeDue)) {
329	    candidates.push({ type: "before_due", date: beforeDue, time: REMINDER_TIME, priority: 1 });
330	  }
331	  if (failed) {
332	    // Sent when the collection fails, not at 10:00: the attempt is at 6pm. Inside 8am–10pm.
333	    candidates.push({ type: "not_collected", date: due, time: failed.time, priority: 0 });
334	  }
335	  if (lateKnown) {
336	    for (let d = addDays(due, LATE_REMINDER_EVERY_DAYS); d < advance.default_date; d = addDays(d, LATE_REMINDER_EVERY_DAYS)) {
337	      if (owedOn(d)) candidates.push({ type: "late", date: d, time: REMINDER_TIME, priority: 2 });
338	    }
339	    const beforeDefault = addDays(advance.default_date, -NOTICE_DAYS_BEFORE_DEFAULT);
340	    if (owedOn(beforeDefault)) {
341	      candidates.push({ type: "before_default", date: beforeDefault, time: REMINDER_TIME, priority: 0 });
342	    }
343	  }
344	
345	  const reported = advance.payroll_delay_reported_on;
346	  const pausedAfter = reported != null && reported <= today ? reported : null;
347	  const kept = [];
348	  const out = [];
349	  candidates.sort((a, b) => a.priority - b.priority || a.date.localeCompare(b.date));
350	  for (const c of candidates) {
351	    if (pausedAfter && c.date > pausedAfter && !NEVER_PAUSED.includes(c.type)) {
352	      out.push({ ...c, status: "paused" });
353	    } else if (fitsCap(kept, c.date)) {
354	      kept.push(c);
355	      out.push({ ...c, status: c.date <= today ? "sent" : "scheduled" });
356	    }
357	  }
358	  return out
359	    .sort((a, b) => a.date.localeCompare(b.date) || a.time.localeCompare(b.time))
360	    .map(({ priority, ...reminder }) => reminder);
361	}
