363	// ---- Wallet ----------------------------------------------------------------
364	
365	// Decided: show the real balance, with "Includes Rs X from your advance" beneath it,
366	// on home after accepting only. Spending isn't modelled ("with more time"), so after
367	// the payout day the balance is unknown: null, never a guess. Elsewhere the advance
368	// card reads from the advance itself (disbursed_amount, received_on, total, due_date).
369	export function getWallet(persona, advance, today) {
370	  if (persona.wallet_balance == null) return { balance: null, includes_advance: null };
371	  if (!advance) return { balance: persona.wallet_balance, includes_advance: null };
372	  if (today !== advance.received_on) return { balance: null, includes_advance: null };
373	  return {
374	    balance: persona.wallet_balance + advance.disbursed_amount,
375	    includes_advance: advance.disbursed_amount,
376	  };
377	}
