379	// ---- Formatting dates and times --------------------------------------------
380	
381	export function formatDate(date) {
382	  if (date == null) return null;
383	  const [, m, d] = date.split("-").map(Number);
384	  return `${d} ${MONTHS[m - 1]}`;
385	}
386	
387	// "Today" when the date is today, otherwise the date ("28 Jun").
388	export function formatDay(date, today) {
389	  if (date == null) return null;
390	  return date === today ? "Today" : formatDate(date);
391	}
392	
393	export function formatTime(time) {
394	  if (time == null) return null;
395	  const [h, min] = time.split(":").map(Number);
396	  const suffix = h < 12 ? "am" : "pm";
397	  const hour = h % 12 || 12;
398	  return min ? `${hour}:${pad(min)}${suffix}` : `${hour}${suffix}`;
399	}
