421	export function scenario(id, { reason = "salary_not_arrived" } = {}) {
422	  if (!SCENARIO_IDS.includes(id)) throw new Error(`Unknown scenario ${id}`);
423	  const today = SCENARIO_DATES[id] ?? PROTOTYPE_TODAY;
424	  if (id === "S2") {
425	    const B = PERSONAS.B;
426	    return { id, persona: B, today, offer: getOffer(B, today), terms: null, advance: null };
427	  }
428	
