434	  if (id === "S7") return { ...base, terms: reducePayout(terms) };
435	
436	  let advance = acceptTerms(terms, { permission_granted: true }, PROTOTYPE_TODAY);
437	  if (["S11", "S12", "S13"].includes(id)) {
438	    advance = collectionOutcome(advance, {
439	      date: advance.due_date,
440	      time: COLLECTION_TIME,
441	      ...NOT_COLLECTED_INPUTS[reason],
442	    });
443	  }
444	  return { ...base, advance };
445	}
