1	// npm run check (part 2): proves the salary-advance module gives the numbers and dates
2	// the screens rely on. Plain Node, nothing installed. See src/advance/salaryAdvance.js.
3	import assert from 'node:assert/strict';
4	import * as SA from '../src/advance/salaryAdvance.js';
5	
6	const { PERSONAS } = SA;
7	const A = PERSONAS.A;
8	const B = PERSONAS.B;
9	const TODAY = SA.PROTOTYPE_TODAY;
10	let passed = 0;
11	const failures = [];
12	
13	function check(name, fn) {
14	  try {
15	    fn();
16	    passed++;
17	  } catch (e) {
18	    failures.push(`  ${name}\n    ${e.message.split('\n').join('\n    ')}`);
19	  }
20	}
21	
22	// Helpers that build the late path for persona A.
23	const terms10k = () => SA.getTerms(A, 10000, TODAY);
24	const accept = (t = terms10k()) => SA.acceptTerms(t, { permission_granted: true }, TODAY);
25	const notCollected = (advance, overrides = {}) =>
26	  SA.collectionOutcome(advance, {
27	    date: '2026-07-28', time: SA.COLLECTION_TIME,
28	    salary_landed: false, salary_amount: null, balance: 1800, salary_destination: 'novapay',
29	    ...overrides,
30	  });
31	const daysApart = (a, b) => Math.round((Date.parse(b) - Date.parse(a)) / 86400000);
32	
33	// ---- Offer ----
34	
35	check('Persona A offer: limit, due date, days until due, 6pm collection', () => {
36	  const o = SA.getOffer(A, TODAY);
37	  assert.equal(o.eligibility, 'eligible');
38	  assert.equal(o.limit, 10000);
39	  assert.equal(o.due_date, '2026-07-28');
40	  assert.equal(o.days_until_due, 21);
41	  assert.equal(o.collection_time, '18:00');
42	});
43	
44	check('Persona A tiers: ascending, fee in rupees, total, 15,000 blocked over the limit', () => {
45	  assert.deepEqual(SA.getOffer(A, TODAY).tiers, [
46	    { amount: 5000, fee: 150, total: 5150, available: true, blocked_reason: null },
47	    { amount: 10000, fee: 300, total: 10300, available: true, blocked_reason: null },
48	    { amount: 15000, fee: null, total: null, available: false, blocked_reason: 'over_limit' },
49	  ]);
50	});
51	
52	check('Persona B needs verification, and nothing unknown shows as 0', () => {
53	  assert.deepEqual(SA.getOffer(B, TODAY), {
54	    eligibility: 'needs_verification', limit: null, due_date: null, days_until_due: null,
55	    collection_time: null, tiers: null,
56	  });
57	});
58	
59	// ---- Terms ----
