          {activity.map((row) => (
            <ListRow
              key={row.id}
              icon={row.direction === "in" ? "↓" : "↑"}
              title={row.title}
              subtitle={formatDay(row.date, today)}
              trailing={<AmountText amount={row.amount} size="body" sign={row.direction === "in" ? "+" : "-"} />}
            />
          ))}
        </Card>
      ) : null}
    </Frame>
  );
}

