/**
 * ListRow / TransactionRow — NovaKit Lite
 * leading icon · title + subtitle · trailing amount
 *
 * - wrap (default false): title and subtitle wrap instead of truncating. Use it
 *   wherever cutting the text would hide a term, a date or an amount.
 * - The icon is decorative and hidden from screen readers. Put any meaning it
 *   carries ("Received", "Collected") in the title or subtitle.
 * - Any other props go to the row's <div>.
 * - Known gap, flagged not fixed: rows are <div>s, not list or description-list items.
 */
export default function ListRow({
  icon = null,
  title,
  subtitle,
  trailing = null,
  wrap = false,
  className = "",
  ...rest
}) {
  const text = wrap ? "" : "truncate";
  return (
    <div
      {...rest}
      className={
        "flex items-center gap-3 py-3 border-b border-neutral-300 last:border-b-0 " +
        className
      }
    >
      {icon ? (
        <div
          aria-hidden="true"
          className="h-9 w-9 rounded-full bg-neutral-100 flex items-center justify-center text-neutral-700 shrink-0"
        >
          {icon}
        </div>
      ) : null}
      <div className="min-w-0 flex-1">
        <div className={`text-body text-neutral-900 ${text}`}>{title}</div>
        {subtitle ? (
/**
 * Toast — NovaKit Lite
 * A transient message.
 * Variants: success (default) | neutral
 *
 * - success confirms something that worked, with a ✓.
 * - neutral explains something that didn't happen and isn't a failure (for example,
 *   tapping an option that isn't available). No icon, no colour meaning.
 * - Failures never use a Toast: they're an inline Card with role="alert".
 * - Known gap, flagged not fixed: no aria-live. Put anything a screen-reader user
 *   needs somewhere they'll hear it (a description, a status region).
 */
export default function Toast({ open, message, variant = "success" }) {
  if (!open) return null;
  const variants = {
    success: "bg-success text-white",
    neutral: "bg-neutral-900 text-white",
  };
  return (
    <div className="absolute left-4 right-4 bottom-6 z-30">
      <div
        className={`flex items-center gap-2 rounded-md px-4 py-3 text-body shadow-card ${variants[variant] || variants.success}`}
      >
        {variant === "success" ? <span aria-hidden="true">✓</span> : null}
        <span>{message}</span>
      </div>
    </div>
  );
}
