const wait = (ms = 250) => new Promise(r => setTimeout(r, ms));
const frame = () => document.querySelector('main').parentElement.parentElement;
const small = async (fn) => { const f = frame(); f.style.width = '360px'; f.style.height = '640px'; await wait(); const r = fn(); f.style.width = ''; f.style.height = ''; return r; };
const out = {};
// details at 360x640 (we're on details now)
out.details360 = await small(() => { const m = document.querySelector('main').getBoundingClientRect(); const cards = [...document.querySelectorAll('main > *')].slice(0, 2).map(c => Math.round(c.getBoundingClientRect().bottom)); return { mainBottom: Math.round(m.bottom), statusCardsBottom: cards, footerVisible: !!document.querySelector('footer') }; });
document.querySelector('header button').click(); await wait();
out.home360 = await small(() => { const m = document.querySelector('main').getBoundingClientRect(); const b = [...document.querySelectorAll('main button')].find(x => x.textContent === 'See details').getBoundingClientRect(); return { mainBottom: Math.round(m.bottom), seeDetailsBottom: Math.round(b.bottom) }; });
const det = async () => { [...document.querySelectorAll('main button')].find(x => x.textContent === 'See details').click(); await wait(); const r = { heading: [...document.querySelectorAll('main h2')].map(h => h.textContent), footer: document.querySelector('footer')?.innerText ?? null, alert: !!document.querySelector('main [role=alert]') }; document.querySelector('header button').click(); await wait(); return r; };
for (const id of ['S10', 'S12']) { document.querySelector(`aside input[name=review-date][value=${id}]`).click(); await wait(); out[id] = { danger: !!document.querySelector('main [role=alert]'), card: document.querySelector('main').innerText.split('\n').filter(Boolean).slice(2, 5), details: await det() }; }
out

