              once your salary arrives.
            </p>
          </div>
          <Button onClick={onStartAdvance}>See amounts and costs</Button>
        </Card>
      ) : null}

      {activity.length ? (
        <Card>
          <h2 className="text-caption text-neutral-700 mb-1">Recent activity</h2>
