const wait = (ms = 250) => new Promise(r => setTimeout(r, ms));
const frame = () => document.querySelector('main').parentElement.parentElement;
const measure = async () => { const r = {}; for (const [w, h] of [[390, 844], [360, 640]]) { const f = frame(); f.style.width = w + 'px'; f.style.height = h + 'px'; await wait(); const m = document.querySelector('main').getBoundingClientRect(); const c = document.querySelector('main').firstElementChild.getBoundingClientRect(); r[w] = { statusCardBottom: Math.round(c.bottom - m.top), visibleMain: Math.round(m.height), fits: c.bottom <= m.bottom }; f.style.width = ''; f.style.height = ''; } await wait(100); return r; };
const out = {};
out.reported = await measure();
// open details fresh while already reported: focus should be the h1, not the confirmation
document.querySelector('header button').click(); await wait();
[...document.querySelectorAll('main button')].find(b => b.textContent === 'See details').click(); await wait();
out.openAlreadyReported = { focused: document.activeElement.tagName };
// untick the reviewer checkbox: back to not reported
document.querySelector('aside input[type=checkbox]').click(); await wait();
[...document.querySelectorAll('main button')].find(b => b.textContent === 'See details').click(); await wait();
out.notReportedFooter = document.querySelector('footer')?.innerText.split('\n');
out.notReported = await measure();
document.querySelector('header button').click(); await wait();
const card = () => { const l = document.querySelector('main').innerText.split('\n').filter(Boolean); const i = l.indexOf('Your salary advance'); return l.slice(i, i + 3).join(' | '); };
for (const id of ['S10', 'S11', 'S13']) { document.querySelector(`aside input[name=review-date][value=${id}]`).click(); await wait(); out[id] = { card: card(), danger: !!document.querySelector('main [role=alert]') }; }
out

