document.querySelector('aside input[name=review-date][value=S13]').click(); await wait();
[...document.querySelectorAll('main button')].find(b => b.textContent === 'See details').click(); await wait();
const main = document.querySelector('main');
const f = main.parentElement.parentElement;
const status = (reported) => `
<p class="text-caption font-semibold text-attention-600">Default date: 27 Aug</p>
<p class="text-body text-neutral-900 mt-1">If it's still unpaid on <span class="font-semibold">27 Aug</span>, the advance is in default. That's in 7 days.</p>
<p class="text-caption text-neutral-700 mt-1">Then new advances are paused and automatic collection stops. We won't freeze your wallet.</p>
<p class="text-body text-neutral-900 mt-2"><span class="font-semibold">Rs 10,300</span> still to repay. The amount hasn't changed and no fee was added.</p>
<p class="text-caption text-neutral-700 mt-1">We couldn't take it on 28 Jul because your salary hadn't arrived.</p>
<p class="text-caption text-neutral-700 mt-1">When your salary arrives in NovaPay, we'll take it automatically, so there's nothing you need to do. The permission you gave us ends on 27 Aug.</p>
${reported ? '<p class="text-body text-neutral-900 mt-2">You told us your salary is late, so the other reminders are paused. This notice is always sent, because it\'s about the date your advance goes into default.</p>' : ''}
<button class="inline-flex items-center min-h-11 rounded-sm text-body font-semibold text-brand">What happens if it's late</button>`;
// The existing S12 card is first; replace its content with the S13 draft.
const card = main.firstElementChild;
const footer = document.querySelector('footer');
footer.innerHTML = '<button class="inline-flex flex-col items-center justify-center text-center rounded-md font-semibold w-full py-2 min-h-11 px-4 text-body bg-white text-neutral-900 border border-neutral-300">Pay some or all yourself</button>';
const out = {};
for (const reported of [false, true]) {
  card.innerHTML = status(reported);
  for (const [w, h] of [[390, 844], [360, 640]]) {
    f.style.width = w + 'px'; f.style.height = h + 'px'; await wait();
    const m = main.getBoundingClientRect(), c = card.getBoundingClientRect();
