              <LateLabel days={status.days_late} />
            </div>
            <div className="mt-1">
              <LateStatus status={status} />
            </div>
          </div>
          <Button variant="secondary" onClick={onSeeAdvance}>
            See details
          </Button>
        </Card>
      ) : advance && offer.eligibility === "has_advance" ? (
        <Card className="space-y-3">
          <div>
