const wait = (ms = 250) => new Promise(r => setTimeout(r, ms));
const openDetails = async () => { [...document.querySelectorAll('main button')].find(b => b.textContent === 'See details').click(); await wait(); };
const home = async () => { document.querySelector('header button').click(); await wait(); };
const measure = async () => { const r = {}; for (const [w, h] of [[390, 844], [360, 640]]) { const f = document.querySelector('main').parentElement.parentElement; f.style.width = w + 'px'; f.style.height = h + 'px'; await wait(); const m = document.querySelector('main').getBoundingClientRect(); const c = document.querySelector('main').firstElementChild.getBoundingClientRect(); r[w] = { cardBottom: Math.round(c.bottom - m.top), visible: Math.round(m.height), fits: c.bottom <= m.bottom }; f.style.width = ''; f.style.height = ''; } await wait(100); return r; };
const out = {};
await openDetails();
out.notReported = { text: document.querySelector('main').firstElementChild.innerText.split('\n').filter(Boolean), footer: document.querySelector('footer')?.innerText.split('\n'), size: await measure() };
await home();
document.querySelector('aside input[type=checkbox]').click(); await wait();
await openDetails();
out.reported = { last: document.querySelector('main').firstElementChild.innerText.split('\n').filter(Boolean).slice(-2), footer: document.querySelector('footer')?.innerText.split('\n'), size: await measure() };
await home();
document.querySelector('aside input[type=checkbox]').click(); await wait();
for (const id of ['S12', 'S11', 'S10']) { document.querySelector(`aside input[name=review-date][value=${id}]`).click(); await wait(); const l = document.querySelector('main').innerText.split('\n').filter(Boolean); const i = l.indexOf('Your salary advance'); out[id] = l.slice(i + 1, i + 3).join(' | '); if (id === 'S12') { await openDetails(); out.S12footer = document.querySelector('footer')?.innerText.split('\n'); await home(); } }
